from apn_mojo import Rational
from polynomials import QQ, DensePoly, NoContext, Budget
from polynomials._algebraic_filter import _gcd_modular
from std.sys import argv
from std.time import perf_counter_ns

def polynomial(line: String, mut budget: Budget) raises -> DensePoly[QQ]:
    var coefficients=List[QQ]()
    if line:
        for token in line.split(","):
            coefficients.append(QQ(Rational(String(token))))
    return DensePoly[QQ].from_coefficients(0, NoContext(), coefficients^, budget)

def main() raises:
    var args=argv()
    var lines=open(String(args[1]), "r").read().splitlines()
    var an=Int(lines[0])
    var bn=Int(lines[1])
    var work=Budget()
    var a=List[DensePoly[QQ]]()
    var b=List[DensePoly[QQ]]()
    for i in range(an):
        a.append(polynomial(String(lines[2+i]), work))
    for i in range(bn):
        b.append(polynomial(String(lines[2+an+i]), work))
    var m=polynomial(String(lines[2+an+bn]), work)
    var start=perf_counter_ns()
    var result=_gcd_modular(a,b,m,work,prime_limit=Int(args[2]))
    print("elapsed ns",perf_counter_ns()-start,"found",Bool(result))
    if result:
        var bits=0
        for row in result.value():
            for c in row.coefficients:
                bits=max(bits,max(c.value.numerator().magnitude_bit_length(),c.value.denominator().magnitude_bit_length()))
        print("degree",len(result.value())-1,"maximum coefficient bits",bits)
